/** formatting function to create a formating string for the console string
@param - b - Bold
@param - c - Color
@param - x - Font Size
@param - i - Italic
*/
function e(b, c, x, i) {
  x = x || 11;
  var n = `font-family: "Helvetica Neue", Helvetica, Arial, sans-serif; font-size: ${x}px; ${
    b ? "font-weight: bold;" : "font-weight: normal;"
  }  ${i ? "font-style: italic;" : ""} color: ${c}; `;
  return n;
}

