/** Read local storage for settings
Reads local storage
  If first time, initializes the control data,
  Otherwise reads the control data and the observed properties
*/
chrome.storage.local.getBytesInUse("gaControlData", function (r) {
  if (r > 0) {
    // There are settings, so get them, then start inspecting
    chrome.storage.local.get("gaControlData", inspect);
    chrome.storage.local.get("observered_ga_properties", function (r) {
      observered_ga_properties = r["observered_ga_properties"] || {};
    });
  } else {
    // This is the first time loading this extension
    inspect({
      gaControlData: {
        inspectingDataLayer: false,
        observed_functions: [],
      },
    });
  }
});

