/* Set a listener for the when the button in GA sends the list of CDs so the cds get saved
 */
window.addEventListener("message", function (event) {
  if (
    event.data &&
    typeof event.data === "string" &&
    event.data.includes("dl-inspector-copied_cd_list")
  ) {
    // Converts the event data to an object
    const data = JSON.parse(event.data);
    // Extracts the cds and the property ID
    let cds = data.payload;
    const propertyID = data.payload.propertyID;
    delete cds.propertyID;
    // Sets cds to the property ID key of the observed ga properties object
    observered_ga_properties[propertyID] = cds;
    // Saves the observed ga properties object to local storage
    chrome.storage.local.set({
      observered_ga_properties: observered_ga_properties,
    });
  }
});

/** Stringify removing unwanted references
@param o - the object to stringify
@param delimiter - the delimiter to use when stringifying
*/
function stringify_removing_unwanted_references(o, delimiter) {
  const TOO_LARGE = "Object is too large to stringify. Expand the object in memory to see details.";
  let key_count = 0;
  if (typeof o === "function") return "Function";
  var cache = [];
  let str_object = "";
  try {
    str_object = JSON.stringify(
      o,
      function (key, value) {
        key_count = key_count + 1;
        if (key_count > 10000) throw new Error(TOO_LARGE);
        if (typeof value === "object" && value !== null) {
          if (cache.indexOf(value) !== -1) {
            // Circular reference found, discard key
            return "Circular Reference";
          } else if (value === window) {
            return "window";
          } else if (value === document) {
            return "document";
          } else if (value instanceof HTMLElement) {
            return `${value.tagName}`;
          } else if (value.tagName === "svg") {
            return `${value.tagName}`;
          }
          // Store value in our collection
          cache.push(value);
        }
        if (value === undefined) value = "undefined (not the string literal)";
        return value;
      },
      delimiter
    );
  } catch (e) {
    if (e.message === TOO_LARGE) {
      str_object = TOO_LARGE;
    } else {
      console.error(e);
    }
  }
  
  cache = null;
  return str_object
    .replace(/\t"([^ ]*)":/g, "\t$1:")
    .replace(/"undefined \(not the string literal\)"/g, "undefined");
}

