const FF_COURIER = '"Courier New", Courier';
/** Format Hit
Utility function
@param b = bold
@param c = color
@param x = size
@param i = italic
@param f = font
*/
function format_hit(b, c, x, i, f) {
  f = f || FF_COURIER;
  x = x || 11;
  var n = `font-family: ${f}; font-size: ${x}px; ${
    b ? "font-weight: bold;" : "font-weight: normal;"
  }  ${i ? "font-style: italic;" : ""} color: ${c}; `;
  return n;
}
const FORMAT_CONSOLE_LOG_HIT = format_hit(false, "inheritied", 14);
